import validator from 'validator';
import { FilterType } from "../components/gms-new-report-modal/gms-new-report-modal.constants"


function validateReportFilters(filters) {
  const invalid_filter = filters.find(
    f => !f.condition.label.includes('null') && (
      // if filter type is a UUID && and is not a valid UUID
      (
        (f.type === 'array' && f.condition.type === FilterType.UUID)
        || (f.type === FilterType.UUID)
      ) && !validator.isUUID(f.filterValue)
    )
  );

  const error = invalid_filter
    ? `Invalid ${invalid_filter.ref || invalid_filter.header_ref}`
    : ``;

  return {
    isValid: !invalid_filter,
    error
  }
}

export default validateReportFilters
